<template>
  <main class="dict-workbench">
    <el-splitter layout="horizontal" class="workspace-splitter">
      <el-splitter-panel :size="leftPanelSize" :min="28" :max="508" @update:size="onLeftSizeChange">
        <div class="left-dock"><nav class="tool-rail"><button :class="{ active: !leftCollapsed }" :title="leftCollapsed ? '显示字典资源' : '隐藏字典资源'" @click="toggleLeft">资源</button></nav><DictResourceTree v-if="!leftCollapsed" :categories="categories" :types="types" :active-type-id="selectedTypeId" @select-type="selectType" @select-category="selectCategory" @new-type="openTypeCreate" @new-item="openItemCreate" @edit-type="openTypeEdit" @toggle-type="toggleType" @delete-type="confirmTypeDelete" @new-category="openCategoryCreate" @edit-category="openCategoryEdit" @delete-category="confirmCategoryDelete" /></div>
      </el-splitter-panel>

      <el-splitter-panel>
        <section class="items-pane">
          <div class="content-heading"><div><span>字典项管理</span><small v-if="selectedType">{{ selectedType.typeName }} ({{ selectedType.typeCode }})</small><small v-else>请从左侧资源区选择字典</small></div><el-button size="small" :disabled="!selectedType" @click="loadItems">↻ 刷新</el-button></div>
          <div class="compact-toolbar"><div class="toolbar-actions"><el-button type="primary" size="small" :disabled="!selectedType" @click="openItemCreate">＋ 新增字典项</el-button><el-button size="small" :disabled="!singleSelectedItem" @click="openItemEdit(singleSelectedItem)">编辑</el-button><el-button size="small" :disabled="!selectedItems.length" @click="confirmItemDelete">删除</el-button><el-button size="small" :disabled="!selectedItems.length" @click="changeItemStatus('ENABLED')">启用</el-button><el-button size="small" :disabled="!selectedItems.length" @click="changeItemStatus('DISABLED')">停用</el-button><el-dropdown><el-button size="small">批量操作⌄</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :disabled="!selectedItems.length" @click="changeItemStatus('ENABLED')">批量启用</el-dropdown-item><el-dropdown-item :disabled="!selectedItems.length" @click="changeItemStatus('DISABLED')">批量停用</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><div class="toolbar-search"><el-input v-model="itemKeyword" size="small" placeholder="搜索标签/值/备注" clearable><template #suffix>⌕</template></el-input></div></div>
          <el-table v-loading="itemsLoading" :data="filteredItems" class="dense-table" highlight-current-row @current-change="handleCurrentItemChange" @selection-change="selectedItems = $event"><el-table-column type="selection" width="42" /><el-table-column prop="itemLabel" label="标签" min-width="180" /><el-table-column prop="itemValue" label="值" min-width="170" class-name="code-cell" /><el-table-column prop="itemSort" label="排序" width="100" /><el-table-column label="状态" width="94"><template #default="{ row }"><StatusBadge :enabled="row.itemStatus === 'ENABLED'" /></template></el-table-column><el-table-column label="备注" min-width="240"><template #default="{ row }"><span class="ellipsis">{{ row.description || '—' }}</span></template></el-table-column></el-table>
          <div class="table-footer"><span>共 {{ filteredItems.length }} 条</span><span>20 条/页</span></div>
        </section>
      </el-splitter-panel>

      <el-splitter-panel v-if="detailVisible" :size="300" :min="300" :max="300">
        <aside class="detail-inspector"><div class="detail-heading">详细信息</div><div v-if="selectedDetail" class="detail-content"><template v-if="selectedDetail.kind === 'type'"><div class="detail-icon">▦</div><h3>{{ selectedDetail.data.typeName }}</h3><code>{{ selectedDetail.data.typeCode }}</code><StatusBadge :enabled="selectedDetail.data.status === 'ENABLED'" /><dl><dt>所属分类</dt><dd>{{ selectedDetail.data.categoryName }}</dd><dt>字典项数量</dt><dd>{{ selectedDetail.data.itemCount }}</dd><dt>更新时间</dt><dd>{{ formatTime(selectedDetail.data.updatedAt) }}</dd><dt>说明</dt><dd>{{ selectedDetail.data.description || '—' }}</dd></dl></template><template v-else-if="selectedDetail.kind === 'item'"><div class="detail-icon">◇</div><h3>{{ selectedDetail.data.itemLabel }}</h3><code>{{ selectedDetail.data.itemValue }}</code><StatusBadge :enabled="selectedDetail.data.itemStatus === 'ENABLED'" /><dl><dt>所属字典</dt><dd>{{ selectedType?.typeName }} ({{ selectedType?.typeCode }})</dd><dt>排序</dt><dd>{{ selectedDetail.data.itemSort }}</dd><dt>更新时间</dt><dd>{{ formatTime(selectedDetail.data.updatedAt) }}</dd><dt>备注</dt><dd>{{ selectedDetail.data.description || '—' }}</dd></dl></template><template v-else><div class="detail-icon">▰</div><h3>{{ selectedDetail.data.categoryName }}</h3><dl><dt>字典数量</dt><dd>{{ selectedDetail.data.dictionaryCount }}</dd><dt>排序</dt><dd>{{ selectedDetail.data.sortOrder }}</dd></dl></template></div><el-empty v-else description="选择字典或字典项查看详情" :image-size="76" /></aside>
      </el-splitter-panel>
    </el-splitter>
    <nav class="tool-rail right-rail"><button :class="{ active: detailVisible }" :title="detailVisible ? '隐藏详细信息' : '显示详细信息'" @click="toggleDetail">详情</button></nav>

    <el-dialog v-model="typeEditorVisible" :title="typeEditorMode === 'create' ? '新建字典' : '编辑字典'" width="460px" destroy-on-close><el-form ref="typeFormRef" :model="typeForm" :rules="typeRules" label-position="top"><el-form-item label="字典名称" prop="typeName"><el-input v-model.trim="typeForm.typeName" placeholder="例如：行政区划" /></el-form-item><el-form-item label="字典编码" prop="typeCode"><el-input v-model.trim="typeForm.typeCode" placeholder="例如：AREA_CODE" :disabled="typeEditorMode === 'edit'" /><p class="field-hint">建议使用大写字母、数字和下划线；编码全局唯一。</p></el-form-item><el-form-item label="所属分类" prop="categoryId"><el-select v-model="typeForm.categoryId" class="full-width"><el-option v-for="category in categories" :key="category.id" :label="category.categoryName" :value="category.id" /></el-select></el-form-item><el-form-item label="说明"><el-input v-model.trim="typeForm.description" type="textarea" :rows="3" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="typeForm.status"><el-radio-button label="ENABLED">启用</el-radio-button><el-radio-button label="DISABLED">停用</el-radio-button></el-radio-group></el-form-item></el-form><template #footer><el-button @click="typeEditorVisible = false">取消</el-button><el-button type="primary" :loading="typeSaving" @click="submitType">保存</el-button></template></el-dialog>
    <el-dialog v-model="itemEditorVisible" :title="itemEditorMode === 'create' ? '新增字典项' : '编辑字典项'" width="460px" destroy-on-close><el-form ref="itemFormRef" :model="itemForm" :rules="itemRules" label-position="top"><el-form-item label="所属字典"><el-input :model-value="selectedType ? `${selectedType.typeName} (${selectedType.typeCode})` : ''" disabled /></el-form-item><el-form-item label="标签" prop="itemLabel"><el-input v-model.trim="itemForm.itemLabel" placeholder="用户看到的文字，例如：启用" /></el-form-item><el-form-item label="值" prop="itemValue"><el-input v-model.trim="itemForm.itemValue" placeholder="程序使用的值，例如：1" /></el-form-item><div class="form-grid"><el-form-item label="排序"><el-input-number v-model="itemForm.itemSort" :min="0" controls-position="right" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="itemForm.itemStatus"><el-radio-button label="ENABLED">启用</el-radio-button><el-radio-button label="DISABLED">停用</el-radio-button></el-radio-group></el-form-item></div><el-form-item label="备注"><el-input v-model.trim="itemForm.description" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><el-button @click="itemEditorVisible = false">取消</el-button><el-button type="primary" :loading="itemSaving" @click="submitItem">保存</el-button></template></el-dialog>
    <el-dialog v-model="categoryEditorVisible" :title="categoryForm.id ? '编辑字典分类' : '新建字典分类'" width="420px"><el-form ref="categoryFormRef" :model="categoryForm" :rules="categoryRules" label-position="top"><el-form-item label="分类名称" prop="categoryName"><el-input v-model.trim="categoryForm.categoryName" /></el-form-item><el-form-item label="排序"><el-input-number v-model="categoryForm.sortOrder" :min="0" controls-position="right" /></el-form-item></el-form><template #footer><el-button @click="categoryEditorVisible = false">取消</el-button><el-button type="primary" :loading="categorySaving" @click="submitCategory">保存</el-button></template></el-dialog>
  </main>
</template>

<script setup>
import { computed, defineComponent, h, nextTick, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import DictResourceTree from '../components/DictResourceTree.vue'
import { deleteCategory, deleteItem, deleteType, fetchCategories, fetchItemDetail, fetchItems, fetchTypes, saveCategory, saveItem, saveType } from '../api/dictAdminApi'

const StatusBadge = defineComponent({ props: { enabled: Boolean }, setup: props => () => h('span', { class: ['status-badge', { disabled: !props.enabled }] }, [h('i'), props.enabled ? '启用' : '停用']) })
const categories = ref([]), types = ref([]), items = ref([]), itemKeyword = ref(''), selectedTypeId = ref(), selectedItems = ref([]), selectedDetail = ref()
const itemsLoading = ref(false), leftWidth = ref(Number(localStorage.getItem('dict.sidebar-width')) || 260), leftCollapsed = ref(localStorage.getItem('dict.sidebar') === 'collapsed'), detailVisible = ref(localStorage.getItem('dict.detail') !== 'collapsed')
const typeFormRef = ref(), itemFormRef = ref(), categoryFormRef = ref(), typeEditorVisible = ref(false), itemEditorVisible = ref(false), categoryEditorVisible = ref(false), typeEditorMode = ref('create'), itemEditorMode = ref('create'), typeSaving = ref(false), itemSaving = ref(false), categorySaving = ref(false)
const typeForm = reactive(newType()), itemForm = reactive(newItem()), categoryForm = reactive(newCategory())
const typeRules = { typeName: [{ required: true, message: '请输入字典名称', trigger: 'blur' }], typeCode: [{ required: true, validator: validateCode, trigger: 'blur' }], categoryId: [{ required: true, message: '请选择所属分类', trigger: 'change' }] }, itemRules = { itemLabel: [{ required: true, message: '请输入标签', trigger: 'blur' }], itemValue: [{ required: true, message: '请输入值', trigger: 'blur' }] }, categoryRules = { categoryName: [{ required: true, message: '请输入分类名称', trigger: 'blur' }] }
const selectedType = computed(() => types.value.find(type => type.id === selectedTypeId.value)), filteredItems = computed(() => { const keyword = itemKeyword.value.trim().toLowerCase(); return items.value.filter(item => !keyword || `${item.itemLabel} ${item.itemValue} ${item.description || ''}`.toLowerCase().includes(keyword)) }), singleSelectedItem = computed(() => selectedItems.value.length === 1 ? selectedItems.value[0] : undefined), leftPanelSize = computed(() => leftCollapsed.value ? 28 : leftWidth.value + 28)
onMounted(loadWorkspace)
async function loadWorkspace() { try { const [categoryData, typeData] = await Promise.all([fetchCategories(), fetchTypes()]); categories.value = categoryData; types.value = typeData; if (!selectedType.value && typeData.length) await selectType(typeData[0]); else if (selectedType.value) await loadItems() } catch (error) { ElMessage.error(error.message || '加载字典数据失败') } }
function toggleLeft() { leftCollapsed.value = !leftCollapsed.value; localStorage.setItem('dict.sidebar', leftCollapsed.value ? 'collapsed' : 'open') } function toggleDetail() { detailVisible.value = !detailVisible.value; localStorage.setItem('dict.detail', detailVisible.value ? 'open' : 'collapsed') }
function onLeftSizeChange(size) { const width = Math.round(Number(size) - 28); if (!Number.isFinite(width)) return; leftWidth.value = Math.min(Math.max(width, 190), 480); localStorage.setItem('dict.sidebar-width', String(leftWidth.value)) }
async function selectType(type) { selectedTypeId.value = type.id; selectedItems.value = []; selectedDetail.value = { kind: 'type', data: type }; await loadItems() } function selectCategory(category) { selectedDetail.value = { kind: 'category', data: category } }
async function loadItems() { if (!selectedTypeId.value) return; itemsLoading.value = true; try { items.value = await fetchItems(selectedTypeId.value) } catch (error) { ElMessage.error(error.message || '加载字典项失败') } finally { itemsLoading.value = false } } function handleCurrentItemChange(row) { if (row) selectedDetail.value = { kind: 'item', data: row } }
function validateCode(_rule, value, callback) { callback(/^[A-Z][A-Z0-9_]*$/.test(value || '') ? undefined : new Error('请输入大写字母、数字和下划线组成的编码')) }
async function openTypeCreate(category) { typeEditorMode.value = 'create'; Object.assign(typeForm, newType({ categoryId: category?.id || selectedType.value?.categoryId || categories.value[0]?.id })); typeEditorVisible.value = true; await nextTick(); typeFormRef.value?.clearValidate() } async function openTypeEdit(row) { typeEditorMode.value = 'edit'; Object.assign(typeForm, newType(row)); typeEditorVisible.value = true; await nextTick(); typeFormRef.value?.clearValidate() }
async function submitType() { try { await typeFormRef.value?.validate(); typeSaving.value = true; await saveType({ ...typeForm }); const code = typeForm.typeCode; typeEditorVisible.value = false; await loadWorkspace(); const saved = types.value.find(type => type.typeCode === code); if (saved) await selectType(saved); ElMessage.success('字典已保存') } catch (error) { if (error?.message) ElMessage.error(error.message) } finally { typeSaving.value = false } }
async function confirmTypeDelete(row = selectedType.value) { if (!row) return; try { await ElMessageBox.confirm(`确定删除字典“${row.typeName}”吗？未删除字典项的字典无法删除。`, '删除字典', { type: 'warning' }); await deleteType(row.id); if (selectedTypeId.value === row.id) { selectedTypeId.value = undefined; selectedDetail.value = undefined; items.value = [] } await loadWorkspace(); ElMessage.success('字典已删除') } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.message || '删除字典失败') } } async function toggleType(row) { try { await saveType({ ...row, status: row.status === 'ENABLED' ? 'DISABLED' : 'ENABLED' }); await loadWorkspace(); const saved = types.value.find(type => type.id === row.id); if (saved) selectedDetail.value = { kind: 'type', data: saved }; ElMessage.success('字典状态已更新') } catch (error) { ElMessage.error(error.message || '更新字典状态失败') } }
async function openItemCreate(type = selectedType.value) { if (!type) return; if (selectedTypeId.value !== type.id) await selectType(type); itemEditorMode.value = 'create'; Object.assign(itemForm, newItem({ typeId: type.id })); itemEditorVisible.value = true; await nextTick(); itemFormRef.value?.clearValidate() } async function openItemEdit(row) { try { itemEditorMode.value = 'edit'; Object.assign(itemForm, newItem(await fetchItemDetail(row.id))); itemEditorVisible.value = true; await nextTick(); itemFormRef.value?.clearValidate() } catch (error) { ElMessage.error(error.message || '加载字典项失败') } }
async function submitItem() { try { await itemFormRef.value?.validate(); itemSaving.value = true; await saveItem({ ...itemForm }); itemEditorVisible.value = false; await Promise.all([loadItems(), loadWorkspace()]); ElMessage.success('字典项已保存') } catch (error) { if (error?.message) ElMessage.error(error.message) } finally { itemSaving.value = false } } async function confirmItemDelete() { if (!selectedItems.value.length) return; try { await ElMessageBox.confirm(`确定删除选中的 ${selectedItems.value.length} 个字典项吗？`, '删除字典项', { type: 'warning' }); await Promise.all(selectedItems.value.map(row => deleteItem(row.id))); selectedItems.value = []; await Promise.all([loadItems(), loadWorkspace()]); ElMessage.success('字典项已删除') } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.message || '删除字典项失败') } } async function changeItemStatus(itemStatus) { if (!selectedItems.value.length) return; try { await Promise.all(selectedItems.value.map(row => saveItem({ ...row, itemStatus }))); await loadItems(); ElMessage.success(`已${itemStatus === 'ENABLED' ? '启用' : '停用'} ${selectedItems.value.length} 个字典项`) } catch (error) { ElMessage.error(error.message || '更新字典项状态失败') } }
function openCategoryCreate() { Object.assign(categoryForm, newCategory()); categoryEditorVisible.value = true; nextTick(() => categoryFormRef.value?.clearValidate()) } function openCategoryEdit(row) { Object.assign(categoryForm, newCategory(row)); categoryEditorVisible.value = true; nextTick(() => categoryFormRef.value?.clearValidate()) } async function submitCategory() { try { await categoryFormRef.value?.validate(); categorySaving.value = true; await saveCategory({ ...categoryForm }); categoryEditorVisible.value = false; await loadWorkspace(); ElMessage.success('分类已保存') } catch (error) { if (error?.message) ElMessage.error(error.message) } finally { categorySaving.value = false } } async function confirmCategoryDelete(row) { try { await ElMessageBox.confirm(`确定删除分类“${row.categoryName}”吗？`, '删除分类', { type: 'warning' }); await deleteCategory(row.id); await loadWorkspace(); ElMessage.success('分类已删除') } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error.message || '删除分类失败') } }
function formatTime(value) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString('zh-CN', { hour12: false }).replaceAll('/', '-') } function newType(source = {}) { return { id: source.id ?? null, categoryId: source.categoryId ?? null, typeCode: source.typeCode ?? '', typeName: source.typeName ?? '', status: source.status ?? 'ENABLED', description: source.description ?? '' } } function newItem(source = {}) { return { id: source.id ?? null, typeId: source.typeId ?? selectedTypeId.value ?? null, itemValue: source.itemValue ?? '', itemLabel: source.itemLabel ?? '', itemSort: source.itemSort ?? 100, itemStatus: source.itemStatus ?? 'ENABLED', description: source.description ?? '' } } function newCategory(source = {}) { return { id: source.id ?? null, categoryName: source.categoryName ?? '', sortOrder: source.sortOrder ?? 100 } }
</script>

<style scoped>
.dict-workbench{--font:var(--shell-font-sans,"Segoe UI","PingFang SC",sans-serif);--surface:var(--shell-tool-surface,#fcfcfd);--surface-raised:var(--shell-tool-surface-muted,#f5f7fa);--button:var(--shell-tool-toolbar-bg,#f8fafc);--text:var(--shell-text-primary,#172033);--muted:var(--shell-tool-subtle-text,#64748b);--border:var(--shell-tool-border-strong,rgba(148,163,184,.3));--divider:var(--shell-tool-divider,rgba(148,163,184,.2));--hover:var(--shell-tool-hover,rgba(15,23,42,.04));--selection:var(--shell-tool-selected-bg,rgba(15,118,110,.1));--accent:var(--shell-accent,#0f766e);height:calc(100vh - 40px);min-height:620px;overflow:hidden;border-top:1px solid var(--divider);background:var(--surface);color:var(--text);font-family:var(--font)}.workspace-splitter{height:100%;min-height:0}.left-dock,.right-dock{display:grid;height:100%;min-width:0;min-height:0}.left-dock{grid-template-columns:28px minmax(0,1fr)}.right-dock{grid-template-columns:minmax(0,1fr) 28px}.tool-rail{display:flex;flex-direction:column;align-items:center;border-right:1px solid var(--divider);background:var(--surface-raised)}.right-rail{height:100%;border-right:0;border-left:1px solid var(--divider)}.tool-rail button{display:grid;place-items:center;box-sizing:border-box;width:27px;height:56px;padding:11px 0;border:0;border-bottom:1px solid var(--divider);border-radius:0;background:transparent;color:var(--muted);cursor:pointer;font:11px/1 var(--font);writing-mode:vertical-rl}.tool-rail button:hover{background:var(--hover);color:var(--text)}.tool-rail button.active{background:var(--surface);color:var(--accent);box-shadow:inset 2px 0 var(--accent)}.right-rail button.active{box-shadow:inset -2px 0 var(--accent)}.items-pane{display:flex;height:100%;min-width:0;flex-direction:column;overflow:hidden}.content-heading{display:flex;min-height:48px;align-items:center;justify-content:space-between;gap:12px;padding:0 16px;border-bottom:1px solid var(--divider);font-size:14px;font-weight:650}.content-heading small{margin-left:10px;color:var(--muted);font-size:12px;font-weight:400}.compact-toolbar{display:flex;min-height:52px;align-items:center;justify-content:space-between;gap:12px;padding:0 16px}.toolbar-actions,.toolbar-search{display:flex;gap:6px;align-items:center}.toolbar-actions{flex-wrap:wrap}.toolbar-search{flex:0 1 300px}.toolbar-search :deep(.el-input){min-width:150px}.compact-toolbar :deep(.el-button),.content-heading :deep(.el-button){--el-button-border-color:var(--border);--el-button-bg-color:var(--surface);--el-button-text-color:var(--muted);height:29px;border-radius:4px}.compact-toolbar :deep(.el-button--primary){--el-button-bg-color:var(--accent);--el-button-border-color:var(--accent);--el-button-text-color:#fff}.dense-table{--el-table-border-color:var(--divider);--el-table-header-bg-color:var(--button);--el-table-tr-bg-color:var(--surface);--el-table-row-hover-bg-color:var(--hover);--el-table-current-row-bg-color:var(--selection);flex:1;font-size:12px}.dense-table :deep(th.el-table__cell){height:36px;padding:0;color:var(--muted);font-size:12px;font-weight:600}.dense-table :deep(td.el-table__cell){height:36px;padding:0}.dense-table :deep(.el-table__inner-wrapper::before){background-color:var(--divider)}.code-cell :deep(.cell),.detail-content code{font-family:Consolas,"JetBrains Mono",monospace}.ellipsis{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.table-footer{display:flex;min-height:44px;align-items:center;padding:0 16px;border-top:1px solid var(--divider);color:var(--muted);font-size:12px}.detail-inspector{display:flex;min-width:0;flex-direction:column;background:var(--surface-raised);overflow:hidden}.detail-heading{min-height:48px;padding:0 16px;border-bottom:1px solid var(--divider);color:var(--text);font-size:14px;font-weight:650;line-height:48px}.detail-content{overflow:auto;padding:24px 18px}.detail-icon{width:38px;height:38px;margin-bottom:14px;border-radius:7px;background:var(--selection);color:var(--accent);font-size:21px;line-height:38px;text-align:center}.detail-content h3{margin:0 0 7px;font-size:17px}.detail-content code{display:block;margin-bottom:13px;color:var(--muted);font-size:12px}.detail-content dl{margin:22px 0}.detail-content dt{margin-top:15px;color:var(--muted);font-size:12px}.detail-content dd{margin:5px 0 0;font-size:13px;line-height:1.55;word-break:break-word}.status-badge{display:inline-flex;align-items:center;gap:5px;width:fit-content;padding:2px 7px;border:1px solid color-mix(in srgb,var(--accent) 25%,transparent);border-radius:3px;background:color-mix(in srgb,var(--accent) 10%,transparent);color:var(--accent);font-size:12px}.status-badge i{width:6px;height:6px;border-radius:50%;background:currentColor}.status-badge.disabled{border-color:var(--border);background:var(--shell-tool-tag-bg);color:var(--muted)}.full-width{width:100%}.field-hint{margin:5px 0 0;color:var(--muted);font-size:12px;line-height:1.45}.form-grid{display:flex;align-items:flex-start;gap:18px}.form-grid :deep(.el-form-item){flex:1}.workspace-splitter :deep(.el-splitter-bar__dragger-horizontal:before){width:1px;background:var(--divider)}.workspace-splitter :deep(.el-splitter-bar__dragger:hover:not(.is-disabled):before){background:var(--accent)}@media(max-width:800px){.dict-workbench{min-width:800px}}
.dict-workbench { display: flex; }
.workspace-splitter { min-width: 0; flex: 1; }
.right-rail { flex: 0 0 28px; }
</style>
